#!/bin/sh
# Claude Code PreToolUse hook for the Dreamstate plugin. Generated by
# packages/cli/scripts/build-agent-plugin.mjs; do not edit by hand.
# Auto-allows 11 read-only Dreamstate MCP tools: packs_get, packs_list, packs_route, runs_events, runs_get, runs_list, skills_get, skills_list, tools_get, tools_search, whoami.
# Anything else, including tools_run and runs_cancel, falls through to the normal prompt.
set -fu

input="$(cat)"

# Tool names look like mcp__plugin_dreamstate_dreamstate__whoami (installed plugin)
# or mcp__dreamstate__whoami (server added by hand).
if printf '%s' "$input" | grep -Eq '"tool_name"[[:space:]]*:[[:space:]]*"mcp__(plugin_dreamstate_dreamstate|dreamstate)__(packs_get|packs_list|packs_route|runs_events|runs_get|runs_list|skills_get|skills_list|tools_get|tools_search|whoami)"'; then
  printf '%s\n' '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"allow","permissionDecisionReason":"Dreamstate plugin auto-allows read-only Dreamstate tools; runs and cancels still prompt"}}'
fi
exit 0
